constexpr uint16_t max_world_x(const HostLevel& lv) {
    const int px = lv.columns * kBlockPx;
    return px > kScreenWidthPx ? static_cast<uint16_t>(px - kScreenWidthPx) : uint16_t{0};
}

constexpr uint16_t kMaxWorldX = max_world_x(kHostLevels[kLevel11]);

// tracks the rom's camera position by driving it exactly as main.c does: 2px per frame, one d-pad
// direction per axis, clamped the same way terrain.c clamps. the test never reads rom-private state.
struct Camera {
    uint16_t x = 0;
    uint8_t y = 0;

    void goto_xy(gb::Gameboy& gameboy, uint16_t target_x, uint8_t target_y) {
        while (x != target_x || y != target_y) {
            const bool right = x < target_x;
            const bool left = x > target_x;
            const bool down = y < target_y;
            const bool up = y > target_y;
            gameboy.set_button(gb::Button::Right, right);
            gameboy.set_button(gb::Button::Left, left);
            gameboy.set_button(gb::Button::Down, down);
            gameboy.set_button(gb::Button::Up, up);
            gameboy.run_frame();
            if (right) {
                x = static_cast<uint16_t>(x + 2);
            }
            if (left) {
                x = static_cast<uint16_t>(x - 2);
            }
            if (down) {
                y = static_cast<uint8_t>(y + 2);
            }
            if (up) {
                y = static_cast<uint8_t>(y - 2);
            }
        }
        gameboy.set_button(gb::Button::Right, false);
        gameboy.set_button(gb::Button::Left, false);
        gameboy.set_button(gb::Button::Down, false);
        gameboy.set_button(gb::Button::Up, false);
    }
};

// scy that brings block row `row` fully into the 144px window (see terrain.c's viewport math)
uint8_t scy_for_row(uint8_t row) {
    const uint16_t px = static_cast<uint16_t>(static_cast<uint16_t>(row) * kBlockPx);
    return static_cast<uint8_t>(px < kScyMax ? px : kScyMax);
}

// scx that brings block column `column` fully into the 160px window, clamped to the level's range
uint16_t scx_for_column(uint16_t column) {
    const uint16_t px = static_cast<uint16_t>(column * kBlockPx);
    return px < kMaxWorldX ? px : kMaxWorldX;
}

// the tile id at the world block (column, row)'s top-left 8x8 cell, given the camera sits at
// (cam_x, cam_y); the caller must have parked the camera so the block is actually on screen
uint8_t block_tile(const gb::Gameboy& gameboy, uint16_t column, uint8_t row, uint16_t cam_x, uint8_t cam_y) {
    const uint32_t screen_x = static_cast<uint32_t>(column) * kBlockPx - cam_x;
    const uint32_t screen_y = static_cast<uint32_t>(row) * kBlockPx - cam_y;
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const uint16_t id = ids[(screen_y + 3) * gb::kLcdWidth + screen_x + 3];
    return static_cast<uint8_t>(id & 0xFFu);
}

// pinned bg tile family ranges per claude-docs/milestones/18-smbd.md's test/tile-id contract and
// the id map recorded in games/mario/src/mario.h. m18's art pass gave most blocks four distinct
// quadrants, so the background outgrew the 0xa0-0xbf block and now also uses the eight ids past
// mario's last sprite frame plus a scenery run borrowed from the font's glyph range. every entry
// here names the family of the block's TOP-LEFT tile, which is the one block_tile() samples
bool tile_in_kind_family(uint8_t tile, uint8_t kind) {
    switch (kind) {
    case kBlockEmpty:
        return tile == 0x00;
    case kBlockGround:
        return tile >= 0xA0 && tile <= 0xA1;
    case kBlockGroundFill:
        return tile >= 0xA2 && tile <= 0xA3;
    case kBlockHard:
    case kBlockStair:
        return tile >= 0xFA && tile <= 0xFD;
    case kBlockBrick:
        return tile >= 0xA4 && tile <= 0xA7;
    case kBlockQuestion:
        return tile >= 0xA8 && tile <= 0xAB;
    case kBlockPipeTl:
    case kBlockPipeTr:
    case kBlockPipeBodyL:
    case kBlockPipeBodyR:
        // m23's rip pass widened the pinned pipe run to twelve tiles, 0xb0-0xbb: the capture's
        // right half is not its left half mirrored and the two cells share no tile column
        return tile >= 0xB0 && tile <= 0xBB;
    // the whole flag is in vram bank 1 now that the shaft stands in the middle of its block: a
    // centred shaft straddles the two tiles of its cell and bank 0 had one id free, not two. the
    // pole's top-left tile is the shaft's black left outline (kTileFlagPoleL, its lit pair is the
    // right tile at 0x5a), the ball's is its left half, and the pennant is 0x31-0x34 - two tiles in
    // the cloth cell's right column and two in the pole cell's left one. the cloth cell's own
    // top-left quadrant is the blank one, because the flag hangs in the right half of that cell
    case kBlockFlagPole:
        return tile == 0x59;
    // m23: the capture draws the ball in the LOWER half of its cell with open sky above it, so the
    // ball's own two tiles (0x30, 0x5d) moved to the block's bottom pair and its top pair is blank
    case kBlockFlagBall:
        return tile == 0x5C;
    case kBlockFlagCloth:
        return tile == 0x5C;
    case kBlockFlagPoleCloth:
        return tile == 0x33;
    case kBlockCastle:
        return tile == 0x22;
    case kBlockCastleCrenel:
        return tile == 0x23;
    case kBlockCastleCrenelInner:
        return tile == 0x5B;
    case kBlockCastleWindow:
    case kBlockCastleWindowRight:
        // the same four tiles, the two columns swapped
        return tile >= 0x24 && tile <= 0x27;
    case kBlockCastleDoorTop:
        return tile >= 0x28 && tile <= 0x2B;
    case kBlockCastleDoor:
        return tile >= 0x2C && tile <= 0x2F;
    case kBlockThin:
        return tile == 0xFE;
    case kBlockLava:
        return tile == 0x20;
    case kBlockLavaFill:
        return tile == 0x18;
    // m20 moved the bridge and the axe into vram bank 1 and gave each of them two tiles, and put
    // the castle's two masonry courses beside them: bank-1 bg 0x12-0x17 (mario.h's castle run)
    case kBlockBridge:
        return tile >= 0x15 && tile <= 0x16;
    case kBlockAxe:
        return tile >= 0x13 && tile <= 0x14;
    // the masonry's two courses: a cell's top pair is the upper one, its bottom pair the lower
    case kBlockCastleBrick:
        return tile == 0x17;
    // m23 measured the capture and found the right cloud cap is NOT the left one mirrored (28 px
    // apart), so it lost its kCamAttrXFlip and took eight tiles of its own at 0xd0-0xd7
    case kBlockCloudTl:
        return tile >= 0x35 && tile <= 0x36;
    case kBlockCloudTr:
        return tile >= 0xD0 && tile <= 0xD1;
    case kBlockCloudT:
        return tile >= 0x39 && tile <= 0x3A;
    case kBlockCloudBl:
        return tile >= 0x3D && tile <= 0x3E;
    case kBlockCloudBr:
        return tile >= 0xD4 && tile <= 0xD5;
    case kBlockCloudB:
        return tile >= 0x41 && tile <= 0x42;
    case kBlockHillPeak:
        return tile >= 0x45 && tile <= 0x46;
    case kBlockHillSlopeL:
    case kBlockHillSlopeR:
        return tile >= 0x49 && tile <= 0x4A;
    case kBlockHillFill:
        return tile >= 0x4D && tile <= 0x4E;
    // a big hill's flat belly cell borrows the fill cell's own flat tile in all four quadrants,
    // so it adds a kind and not one vram id
    case kBlockHillCore:
        return tile == 0x4D;
    case kBlockBushL:
        return tile >= 0x51 && tile <= 0x52;
    // and the right bush cap the same way, at 0xd8-0xdb
    case kBlockBushR:
        return tile >= 0xD8 && tile <= 0xD9;
    case kBlockBushM:
        return tile >= 0x55 && tile <= 0x56;
    // m26 re-cut the canopy off the smbd 1-3 capture and it came out two tiles SMALLER: the
    // capture's right cap is the left one's exact mirror, so kBlockTreeTopR carries the left
    // cap's own tiles under kCamAttrXFlip and the canopy is 0x0a-0x0e with the trunk at 0x0f
    case kBlockTreeTopL:
    case kBlockTreeTopM:
    case kBlockTreeTopR:
        return tile >= kTileTreeFirst && tile <= kTileTreeBotM;
    case kBlockTrunk:
        return tile == kTileTrunk;
    // m25's shaft joint, five bank-1 tiles at 0xe0-0xe4: each kind's top-left tile is its own
    case kBlockPipeJointT:
        return tile == 0xE0;
    case kBlockPipeJointB:
        return tile == 0xE2;
    // the chain's top-left quadrant is empty, the blank scenery cell; its line is 0x1b-0x1c
    case kBlockBridgeChain:
        return tile == 0x5C;
    case kBlockSpent:
        return tile >= kTileSpentLo && tile <= kTileSpentHi;
    case kBlockCoin:
        return tile >= kTileWorldCoinLo && tile <= kTileWorldCoinHi;
    default:
        return false;
    }
}

// every family a terrain cell may legitimately render as: the pinned 0xa0-0xbf block, the eight
// ids past mario's frames, and the scenery run inside what is otherwise the font's own range
bool is_known_terrain_family(uint8_t tile) {
    // 0xd0-0xdd is m23's rip run in vram bank 1: the right cloud cap, the right bush cap and the
    // right half of each castle crenel, none of which the capture lets the rom mirror. 0xe0-0xe4
    // is m25's shaft joint, the one family 1-2's capture holds that 1-1's does not
    return tile <= 0x5F || (tile >= 0xA0 && tile <= 0xBF) || (tile >= 0xD0 && tile <= 0xDD) ||
           (tile >= 0xE0 && tile <= 0xE4) || tile >= 0xF8;
}

// --- sub-milestone 3: the player ---------------------------------------------------------------

// mirrors of games/mario/src/mario.h's player geometry, the same way kBlockPx above mirrors it
constexpr uint8_t kMarioFirstTile = 0xE0;
constexpr uint8_t kMarioTilesPerFrame = 4;
constexpr uint8_t kMarioFrameCount = 6;
constexpr uint8_t kMarioLastTile = kMarioFirstTile + kMarioFrameCount * kMarioTilesPerFrame - 1;
constexpr int kFrameIdle = 0;
constexpr int kFrameWalk0 = 1;
constexpr int kFrameWalk1 = 2;
constexpr int kFrameWalk2 = 3;
constexpr int kFrameSkid = 4;
constexpr int kFrameJump = 5;
// m22's seventh small pose, at four ids of its own outside the pinned family (kTileMarioDeath)
constexpr int kFrameDeath = 6;
constexpr uint8_t kMarioDeathTile = 0x70;
// and his flagpole grip, four more of them in vram bank 1 (mario.h's kTileClimbSmall): its own ids
// rather than the idle pose's, so a tile number alone tells the two poses apart
constexpr uint8_t kMarioClimbTile = 0x74;
// the big set's own seventh and eighth: the fold, and the flagpole grip
constexpr int kFrameCrouch = 6;
constexpr int kFrameClimbBig = 7;
constexpr int kPlayerBoxPx = 16;
constexpr int kPlayScy = kScyMax;

// m22 redrew every pose off the smbd sprite sheet, so no single "art inset" is true any more: the
// stand is 12 px wide and sits 2 in, walk0 is the full 16 and sits flush, the skid is 13 and sits
// one in with two spare on the right. so every pose carries its own lit bounding box inside its
// box, and mario_box_left/top below turn a measured sprite back into the 16 px (or 16x32) box the
// engine actually positions. the numbers are not transcribed: they are DECODED at start-up out of
// the very generated arrays the rom is built from (games/mario/src/gen/mario_*.c, compiled in as
// sprite_art above), so re-ripping the art cannot leave a hand-copied table behind
struct ArtBounds {
    int left;
    int right;
    int top;
    int bottom;
};
// idle, walk0, walk1, walk2, skid, jump, death, then the climb grip as a seventh index
constexpr int kSmallPoseCount = 8;
constexpr int kPoseClimb = 7;

// the lit bounds of one pose, out of a run of 2bpp tiles in png2tiles' sprites16 order: per 16 px
// band of the pose, [left column top 8x8, left column bottom, right column top, right column
// bottom]. so a 16x16 pose is one band of four tiles and a 16x32 pose two bands of eight. inside a
// tile each row is two bytes - the two bitplanes - and a pixel is lit when either plane has its bit,
// bit 7 being the leftmost
ArtBounds art_bounds(const uint8_t* tiles, int bands) {
    ArtBounds a{16, -1, 16 * bands, -1};
    for (int band = 0; band < bands; ++band) {
        for (int column = 0; column < 2; ++column) {
            for (int half = 0; half < 2; ++half) {
                const uint8_t* tile = tiles + (band * 4 + column * 2 + half) * 16;
                for (int row = 0; row < 8; ++row) {
                    const int lit = tile[row * 2] | tile[row * 2 + 1];
                    if (lit == 0) {
                        continue;
                    }
                    const int y = band * 16 + half * 8 + row;
                    a.top = std::min(a.top, y);
                    a.bottom = std::max(a.bottom, y);
                    for (int bit = 0; bit < 8; ++bit) {
                        if ((lit & (0x80 >> bit)) == 0) {
                            continue;
                        }
                        a.left = std::min(a.left, column * 8 + bit);
                        a.right = std::max(a.right, column * 8 + bit);
                    }
                }
            }
        }
    }
    return a;
}

// idle, walk0, walk1, walk2, skid, jump, death out of mario_small.png's seven stacked 16x16 poses,
// and the climb grip - its own png, and the seventh index of this table - after them
std::array<ArtBounds, kSmallPoseCount> decode_small_art() {
    std::array<ArtBounds, kSmallPoseCount> out{};
    for (int pose = 0; pose < kPoseClimb; ++pose) {
        out[static_cast<size_t>(pose)] = art_bounds(sprite_art::kMarioSmallTiles + pose * 4 * 16, 1);
    }
    out[kPoseClimb] = art_bounds(sprite_art::kMarioSmallClimbTiles, 1);
    return out;
}

// idle, walk0, walk1, walk2, skid, jump, crouch, climb - the big set's own eight 16x32 poses, in the
// order games/mario/src/gen/mario_big.c stores them
std::array<ArtBounds, kSmallPoseCount> decode_big_art() {
    std::array<ArtBounds, kSmallPoseCount> out{};
    for (int pose = 0; pose < kSmallPoseCount; ++pose) {
        out[static_cast<size_t>(pose)] = art_bounds(sprite_art::kMarioBigTiles + pose * 8 * 16, 2);
    }
    return out;
}

const std::array<ArtBounds, kSmallPoseCount> kSmallArt = decode_small_art();
const std::array<ArtBounds, kSmallPoseCount> kBigArt = decode_big_art();

// the file select's own geometry, mirrored from games/mario/src/file_art.h: the three pipes mario
// stands over, his standing top edge, and how long the arc between two of them runs
constexpr int kFileMarioX = 24;
constexpr int kFileMarioStep = 48;
constexpr int kFileStandY = 64;
constexpr int kFileHopFrames = 20;
constexpr int kFileSlots = 3;

// --- sub-milestone 7: the powerup chain, mirrored from games/mario/src/mario.h ------------------

// super mario's own tile family. m22's exact art gives every pose its own upper half, so the eight
// 16x32 poses are 64 tiles and they live in CGB VRAM BANK 1 at 0x00-0x3f. a framebuffer tile id
// carries the tile number and a sprite bit but not the bank, and no bank-0 sprite in the game uses
// an id below 0x60, so the range still names him unambiguously
constexpr uint8_t kSuperFirstTile = 0x00;
constexpr uint8_t kSuperLastTile = 0x3F;
constexpr int kSuperTilesPerPose = 8;
constexpr uint8_t kTileFlowerLo = 0x80;
constexpr uint8_t kTileFlowerHi = 0x83;
[[maybe_unused]] constexpr uint8_t kTileStarLo = 0xD4;
[[maybe_unused]] constexpr uint8_t kTileStarHi = 0xD7;
constexpr uint8_t kTileFireballLo = 0xDE;
constexpr uint8_t kTileFireballHi = 0xDF;
constexpr int kPlayerBigBoxPx = 32;
// kMarioCrouchWalkSubpx in games/mario/src/mario.h: the cap on a ducking mario's own walk, half a
// walk's. smb gives him none at all, which left 1-2's one-block crawl space unenterable from a
// standstill; mirrored here the way every other mario.h constant in this file is
constexpr int kCrouchWalkSubpx = 12;
[[maybe_unused]] constexpr int kFireballPx = 8;
constexpr int kGrowFrames = 64;
constexpr uint8_t kContentStar = 3;
constexpr uint8_t kContentNothing = 0;
constexpr uint8_t kBlockListBrick = 1;
// the rgb555 the cgb palettes above put on mario's body: his own red, fire's white, the star's
// yellow. no other sprite family shares them, so a pixel of one on his tiles names his state
// m22 read all three sets off the smbd sheets (assets_load_sprite_palettes/item_palettes), so what
// names his state is whichever colour ONE of the three puts on him and the others do not: kPalMario
// alone has the #736900 dark his hair and shoes are drawn in, kPalFire alone the #ffe3b5 cream that
// replaces the red, and a star's kPalStar alone turns his skin index white
constexpr int kColorMarioDark = 14 | (13 << 5) | (0 << 10);
constexpr int kColorFireCream = 31 | (28 << 5) | (22 << 10);
constexpr int kColorStarWhite = 31 | (31 << 5) | (31 << 10);

// mario's world y while standing on the bible's start cell, in screen px (scy is pinned in play)
constexpr int kStandTop = static_cast<int>(LEVEL_1_1_START_ROW) * kBlockPx - kPlayerBoxPx - kPlayScy;

struct Mario {
    int left = 0;
    int right = 0;
    int top = 0;
    int bottom = 0;
    // the small pose index (kFrame*), or kPoseClimb for the grip. -1 when only big tiles were seen
    int frame = -1;
    // the big pose index, or -1 when he is small
    int pose = -1;
    bool big = false;
    // whichever half of the pose drew at m.left told us which way he is facing: an 8x16 pair's own
    // two tiles are base+0/+1 and the other column's are base+2/+3, so bit 1 of the offset is the
    // whole answer and player_draw's own facing swap is what sets it
    bool facing_left = false;
    bool found = false;

    int height() const {
        return bottom - top + 1;
    }
    // the pose's lit bounds inside its own box, which is what left/right/top/bottom measure
    ArtBounds art() const {
        const int i = big ? (pose < 0 ? 0 : pose) : (frame < 0 ? 0 : frame);
        return big ? kBigArt[i] : kSmallArt[i];
    }
    // the 16 px box the engine positions, recovered from the lit pixels. flipping mirrors the pose
    // inside its own box, so the left inset becomes the right one
    int box_left() const {
        const ArtBounds a = art();
        return left - (facing_left ? (kPlayerBoxPx - 1 - a.right) : a.left);
    }
    int box_right() const {
        return box_left() + kPlayerBoxPx - 1;
    }
    int box_top() const {
        return top - art().top;
    }
    int box_bottom() const {
        return box_top() + (big ? 2 * kPlayerBoxPx : kPlayerBoxPx) - 1;
    }
    // the fold: pose 6 of the big set, whose 22-tall art is bottom-aligned in the same 16x32 box
    bool crouched() const {
        return big && pose == kFrameCrouch;
    }
};
// what height() reads while he is folded: kBigArt[kFrameCrouch] runs rows 10..31 of the box
constexpr int kCrouchArtPx = 22;

Mario mario_at(const gb::Gameboy& gameboy) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    Mario m;
    uint8_t left_tile = 0;
    for (size_t i = 0; i < ids.size(); ++i) {
        if ((ids[i] & 0x100u) == 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        const bool small_tile = (tile >= kMarioFirstTile && tile <= kMarioLastTile) ||
                                (tile >= kMarioDeathTile && tile < kMarioDeathTile + 4) ||
                                (tile >= kMarioClimbTile && tile < kMarioClimbTile + 4);
        const bool big_tile = tile <= kSuperLastTile;
        if (!small_tile && !big_tile) {
            continue;
        }
        const int x = static_cast<int>(i % gb::kLcdWidth);
        const int y = static_cast<int>(i / gb::kLcdWidth);
        if (!m.found || x < m.left) {
            m.left = x;
            left_tile = tile;
        }
        if (!m.found || x > m.right) {
            m.right = x;
        }
        if (!m.found || y < m.top) {
            m.top = y;
        }
        if (!m.found || y > m.bottom) {
            m.bottom = y;
        }
        if (small_tile) {
            // the climb grip shares small mario's idle id in vram bank 1, so a pose read off a tile
            // number alone cannot tell the two apart. it is reported as the idle pose, and the one
            // test that watches the climb asks for kPoseClimb explicitly (see mario_climbs_as)
            m.frame = tile >= kMarioClimbTile && tile < kMarioClimbTile + 4
                          ? kPoseClimb
                          : (tile >= kMarioDeathTile && tile < kMarioDeathTile + 4
                                 ? kFrameDeath
                                 : (tile - kMarioFirstTile) / kMarioTilesPerFrame);
        }
        if (big_tile) {
            m.pose = tile / kSuperTilesPerPose;
        }
        m.big = m.big || big_tile;
        m.found = true;
    }
    if (m.found) {
        const int base =
            m.big ? m.pose * kSuperTilesPerPose
                  : (m.frame == kFrameDeath
                         ? kMarioDeathTile
                         : (m.frame == kPoseClimb ? kMarioClimbTile
                                                  : kMarioFirstTile + m.frame * kMarioTilesPerFrame));
        m.facing_left = ((static_cast<int>(left_tile) - base) & 0x2) != 0;
    }
    return m;
}

// the 16 px box's left edge, which every "where is he" assertion in this file works in
int mario_box_left(const gb::Gameboy& gameboy) {
    return mario_at(gameboy).box_left();
}

// which of the file select's three pipes mario is standing over, or -1 while he is mid-hop between
// two of them. the screen has no text cursor any more - where he stands is the whole answer
int file_cursor(const gb::Gameboy& gameboy) {
    const Mario m = mario_at(gameboy);

    if (!m.found) {
        return -1;
    }
    for (int slot = 0; slot < kFileSlots; ++slot) {
        const int pipe = kFileMarioX + slot * kFileMarioStep;
        if (m.left >= pipe && m.right < pipe + 16) {
            return slot;
        }
    }
    return -1;
}

// 1 when any of mario's own sprite pixels is painted this exact rgb555; the fire and star palettes
// each put a color on him that nothing else on screen uses
bool mario_wears(const gb::Gameboy& gameboy, int rgb555) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const std::span<const uint16_t> colors = gameboy.framebuffer_color();
    for (size_t i = 0; i < ids.size(); ++i) {
        if ((ids[i] & 0x100u) == 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        const bool mine = (tile >= kMarioFirstTile && tile <= kMarioLastTile) ||
                          (tile >= kMarioDeathTile && tile < kMarioDeathTile + 4) ||
                          (tile >= kMarioClimbTile && tile < kMarioClimbTile + 4) || (tile <= kSuperLastTile);
        if (mine && static_cast<int>(colors[i]) == rgb555) {
            return true;
        }
    }
    return false;
}

// a surface ground block is two tiles wide - its left half is 0xa0, its right half 0xa1 - so the
// screen x where a left half follows a right one repeats every 16 px and is pinned to where the
// camera sits inside a block. m18's art pass replaced the 4px speck this used to read, and 16 is a
// stronger anchor than 4 was: no step comes close to being ambiguous at that period
constexpr int kGroundPhaseRow = 13 * kBlockPx + 3 - kPlayScy;
constexpr int kGroundPhasePeriod = 16;

int ground_phase(const gb::Gameboy& gameboy) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    for (int x = 1; x < static_cast<int>(gb::kLcdWidth); ++x) {
        const size_t i = static_cast<size_t>(kGroundPhaseRow) * gb::kLcdWidth + static_cast<size_t>(x);
        if ((ids[i] & 0x100u) != 0 || (ids[i - 1] & 0x100u) != 0) {
            continue;
        }
        if (static_cast<uint8_t>(ids[i]) == 0xA0 && static_cast<uint8_t>(ids[i - 1]) == 0xA1) {
            return x % kGroundPhasePeriod;
        }
    }
    return -1;
}

// the rom never exposes mario's world x, so the test reconstructs it: once the camera follows, his
// screen x is pinned and the whole displacement shows up in the camera's 4px phase; before that the
// camera is parked and it all shows up in his screen x. no step ever exceeds the 2.5 px/frame run
// cap, so the phase difference is unambiguous mod 4.
struct WorldTracker {
    int phase = 0;
    int screen = 0;

    void sync(const gb::Gameboy& gameboy, const Mario& m) {
        phase = ground_phase(gameboy);
        screen = m.box_left();
    }

    int step(const gb::Gameboy& gameboy, const Mario& m) {
        const int next = ground_phase(gameboy);
        const int cam = ((phase - next) % kGroundPhasePeriod + kGroundPhasePeriod) % kGroundPhasePeriod;
        const int moved = cam + (m.box_left() - screen);
        phase = next;
        screen = m.box_left();
        return moved;
    }
};

// the bible's tables, generated straight from physics.json - the same header player.c reads
constexpr int8_t kJumpSpeed[kMarioJumpTierCount] = kMarioJumpSpeedInit;
constexpr uint8_t kGravityRise[kMarioJumpTierCount] = kMarioGravityRiseInit;
constexpr uint8_t kGravityFall[kMarioJumpTierCount] = kMarioGravityFallInit;

// host-side twin of player.c's vertical step: whole-px speed, a 1/256-px accumulator gravity feeds,
// and the bible's hold-a rule. tier 0 because every arc here starts from a standstill.
struct JumpSim {
    int y = kStandTop;
    int8_t speed = 0;
    uint8_t accum = 0;
    uint8_t frac = 0;
    int origin = kStandTop;
    bool grounded = true;
    bool a_prev = false;

    void step(bool a) {
        if (grounded && a && !a_prev) {
            speed = kJumpSpeed[0];
            accum = 0;
            frac = 0;
            origin = y;
            grounded = false;
        }
        uint8_t force = kGravityFall[0];
        if (speed < 0 && ((a && a_prev) || (origin - y) < kMarioMinRisePx)) {
            force = kGravityRise[0];
        }
        // player.c's ImposeGravity: the force's carry is a pixel of travel, then gravity feeds the
        // force, and the terminal speed zeroes the force once it passes half
        const unsigned carry = static_cast<unsigned>(frac) + accum;
        frac = static_cast<uint8_t>(carry);
        y += speed + static_cast<int>(carry >> 8);
        const unsigned sum = static_cast<unsigned>(accum) + force;
        accum = static_cast<uint8_t>(sum);
        if (sum > 0xFFu) {
            speed = static_cast<int8_t>(speed + 1);
        }
        if (speed >= kMarioMaxFallPx && accum >= 0x80u) {
            speed = kMarioMaxFallPx;
            accum = 0;
        }
        // the start cell's floor is flat, so landing is one clamp back onto the standing row
        if (speed >= 0 && y >= kStandTop) {
            y = kStandTop;
            speed = 0;
            frac = 0;
            accum = 0;
            grounded = true;
        }
        a_prev = a;
    }
};

// drives one jump and returns mario's sprite top per frame. the rom reads the buttons set before
// run_frame i on its own frame i, but that frame is only scanned out one frame later, which is
// what the lag the callers measure accounts for.
std::vector<int> jump_tops(gb::Gameboy& gameboy, int hold_frames, int frames) {
    std::vector<int> tops;
    tops.reserve(static_cast<size_t>(frames));
    for (int i = 0; i < frames; ++i) {
        gameboy.set_button(gb::Button::A, i < hold_frames);
        gameboy.run_frame();
        const Mario m = mario_at(gameboy);
        REQUIRE(m.found);
        tops.push_back(m.box_top());
    }
    gameboy.set_button(gb::Button::A, false);
    return tops;
}

// the first frame mario's sprite actually moves; everything before it is the rom's scanout lag
int first_move(const std::vector<int>& tops) {
    for (size_t i = 0; i < tops.size(); ++i) {
        if (tops[i] != kStandTop) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

// holds a direction (plus b to run) and returns the world px covered over the whole window
int travel(gb::Gameboy& gameboy, gb::Button dir, bool run_button, int frames) {
    WorldTracker tracker;
    tracker.sync(gameboy, mario_at(gameboy));
    gameboy.set_button(dir, true);
    gameboy.set_button(gb::Button::B, run_button);
    int total = 0;
    for (int i = 0; i < frames; ++i) {
        gameboy.run_frame();
        total += tracker.step(gameboy, mario_at(gameboy));
    }
    return total;
}

// the leftmost screen x carrying a bg pixel of the given tile family on mario's own rows, or -1
int face_of(const gb::Gameboy& gameboy, const Mario& m, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const int bottom = std::min(m.box_top() + kPlayerBoxPx, static_cast<int>(gb::kLcdHeight));
    for (int x = 0; x < static_cast<int>(gb::kLcdWidth); ++x) {
        for (int y = std::max(m.box_top(), 0); y < bottom; ++y) {
            const size_t i = static_cast<size_t>(y) * gb::kLcdWidth + static_cast<size_t>(x);
            if ((ids[i] & 0x100u) != 0) {
                continue;
            }
            const uint8_t tile = static_cast<uint8_t>(ids[i]);
            if (tile >= lo && tile <= hi) {
                return x;
            }
        }
    }
    return -1;
}

int pipe_face(const gb::Gameboy& gameboy, const Mario& m) {
    return face_of(gameboy, m, 0xB0, 0xB7);
}

// the shaft's lit column, which is the right tile of the pole's cell (kTileFlagPoleR): its first
// pixel column is the lit one, so the x this returns is the shaft itself. the cell's left tile is
// not in the range on purpose - the pennant replaces it at whatever row the flag has reached, and
// the descent would otherwise move the x this reports by half a cell
int pole_face(const gb::Gameboy& gameboy, const Mario& m) {
    return face_of(gameboy, m, 0x5A, 0x5A);
}

// the level's first pipe, from the compiler's own probes rather than the bible's json
uint16_t first_pipe_column() {
    for (const auto& probe : kLevel11Probes) {
        if (probe.kind == kBlockPipeTl) {
            return probe.column;
        }
    }
    return 0;
}

// the level's first pit, taken from the compiler's own probes rather than the bible's json
uint16_t first_gap_column() {
    for (const auto& probe : kLevel11Probes) {
        if (probe.kind == kBlockEmpty && probe.row == 13) {
            return probe.column;
        }
    }
    return 0;
}

// --- sub-milestone 4: the camera, and a host twin of the rom used to plan 1-1 -------------------

// mirrors of games/mario/src/mario.h's camera and hitbox tuning, same convention as kBlockPx above
constexpr int kCamFollowX = 64;
constexpr int kCamLookAheadX = 24;
[[maybe_unused]] constexpr int kCamAnchorStepPx = 2;
constexpr int kCamGroundOffsetPx = 32;
constexpr int kScreenHeightPx = 144;
constexpr int kCamSafeTopPx = 32;
constexpr int kCamSafeBottomPx = kScreenHeightPx - kCamGroundOffsetPx;
constexpr int kCamWindowTopPx = 64;
constexpr int kCamWindowBottomPx = kScreenHeightPx - kCamGroundOffsetPx;
constexpr int kCamEaseMaxPx = 4;
constexpr int kCamEaseShift = 3;
constexpr int kCamAirEaseShift = 2;
constexpr int kCamLookUpPx = 32;
[[maybe_unused]] constexpr int kCamLookDownPx = 24;
constexpr int kCamLookDelayFrames = 24;

// the host twin of games/mario/src/camera.c's vertical rules: a deadzone window in screen space and
// a distance-proportional ease onto whatever it asks for. both sims below share these, so the
// planner's screen predictions stay frame-identical with the rom's.
[[maybe_unused]] inline uint8_t cam_clamp_scy(int value) {
    return static_cast<uint8_t>(std::max(0, std::min(static_cast<int>(kScyMax), value)));
}

inline uint8_t cam_window_target(int feet_world, uint8_t on_ground, uint8_t cam_y) {
    // saturating, exactly as camera_update does: a pit carries his feet past 255, and a byte that
    // wrapped there would send the view up the level after them
    const uint8_t feet = static_cast<uint8_t>(std::max(0, std::min(255, feet_world)));
    const uint8_t top = static_cast<uint8_t>(on_ground != 0 ? kCamWindowTopPx : kCamSafeTopPx);
    const uint8_t bottom = static_cast<uint8_t>(on_ground != 0 ? kCamWindowBottomPx : kCamSafeBottomPx);

    if (feet < static_cast<uint8_t>(cam_y + top)) {
        return feet > top ? static_cast<uint8_t>(feet - top) : uint8_t{0};
    }
    if (feet > static_cast<uint8_t>(cam_y + bottom)) {
        const uint8_t want = static_cast<uint8_t>(feet - bottom);
        return want < static_cast<uint8_t>(kScyMax) ? want : static_cast<uint8_t>(kScyMax);
    }
    return cam_y;
}

inline uint8_t cam_ease(uint8_t cam_y, uint8_t want, uint8_t on_ground) {
    if (want == cam_y) {
        return cam_y;
    }
    const int shift = on_ground != 0 ? kCamEaseShift : kCamAirEaseShift;
    const int gap = std::abs(static_cast<int>(want) - static_cast<int>(cam_y));
    int step = std::max(1, std::min(kCamEaseMaxPx, gap >> shift));
    step = std::min(step, gap);
    return static_cast<uint8_t>(want > cam_y ? cam_y + step : cam_y - step);
}
