    run(gameboy, 30);
    open_pause(gameboy);
    press(gameboy, gb::Button::Down, 2);
    run(gameboy, 2);
    REQUIRE(pause_cursor_row(gameboy) == 1);
    press(gameboy, gb::Button::A, 2);
    run(gameboy, 2);
