    REQUIRE(pause_tile_at(gameboy, kPauseMenuX + 8 * 5 + 3, kPauseMenuY + kPauseMenuStepY + 3) == kGlyphD);
    // slot 0's used flag, mario.h kSaveSlotBase (the save tests below spell the layout out)
    REQUIRE(gameboy.external_ram()[8] == 1);
